def drive(me, enemy, arena):
    dist = distance_to(enemy.x, enemy.y)
    if hypot(me.x, me.y) > 5.2:
        err = bearing_to(0, 0)
        base = 0.8
    else:
        err = bearing_to(enemy.x, enemy.y)
        base = 1.0
        if dist < 1.3:
            base = 0.55

    if abs(err) > 100:
        if err > 0:
            err = err - 180
        else:
            err = err + 180
        base = -base

    if abs(err) > 70:
        base = base * 0.55

    turn = err / 55.0 - me.turn_rate / 140.0
    turn = max(-1.0, min(1.0, turn))
    left = base - turn
    right = base + turn
    scale = max(1.0, abs(left), abs(right))
    return (left / scale, right / scale)


def weapons(me, enemy, arena):
    if me.righting:
        return None

    if me.inverted and not me.airborne:
        return self_right()

    if me.on_side or me.airborne:
        return None

    if enemy.airborne or enemy.righting or enemy.held or enemy.lifted:
        return None

    w = me.weapons.get("front")
    if w is None or w["type"] != "flipper":
        return None

    if w["ready"] and w["shots_left"] > 0:
        if distance_to(enemy.x, enemy.y) < 1.75:
            if abs(bearing_to(enemy.x, enemy.y)) < 35:
                return flip("front")

    return None

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    ex = enemy.x + 0.2 * enemy.vx
    ey = enemy.y + 0.2 * enemy.vy

    r2 = me.x * me.x + me.y * me.y
    if r2 > 25.0:
        if r2 > 36.0:
            ex = 0.0
            ey = 0.0
        else:
            ex = ex - 0.4 * me.x
            ey = ey - 0.4 * me.y

    b = bearing_to(ex, ey)

    if abs(b) > 60.0:
        if b > 0.0:
            return (-0.9, 0.9)
        return (0.9, -0.9)

    corr = b / 60.0
    left = 0.95 - 0.85 * corr
    right = 0.95 + 0.85 * corr

    if left < -1.0:
        left = -1.0
    elif left > 1.0:
        left = 1.0

    if right < -1.0:
        right = -1.0
    elif right > 1.0:
        right = 1.0

    return (left, right)


def weapons(me, enemy, arena):
    if me.battery_health <= 0.0 or me.battery_wh <= 0.0:
        return None

    if me.righting or me.airborne:
        return None

    wp = me.weapons.get("back")

    if me.on_side:
        if wp is not None and wp.get("ready") and wp.get("shots_left", 0) > 0:
            return [self_right()]
        return None

    if me.inverted:
        if wp is not None and wp.get("ready") and wp.get("shots_left", 0) > 0:
            if distance_to(enemy.x, enemy.y) > 1.0:
                return [self_right()]

    rpm = 3500
    if me.battery_health < 0.5:
        rpm = 2000
    if me.battery_wh < 300:
        rpm = 1000

    cmds = [spin("front", rpm)]

    if not me.inverted and not enemy.airborne and not enemy.righting and not enemy.on_side:
        if not enemy.held and not enemy.lifted and enemy.z < 0.05:
            d = distance_to(enemy.x, enemy.y)
            if d < 0.85:
                b = bearing_to(enemy.x, enemy.y)
                if b > 135.0 or b < -135.0:
                    if wp is not None and wp.get("ready") and wp.get("shots_left", 0) > 0:
                        cmds.append(flip("back"))

    return cmds

